PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL; 
    Stop : BOOL; 
    EStop : BOOL; 
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    motorLatch : BOOL;
END_VAR

IF NOT EStop THEN
    Motor := FALSE;
ELSIF Stop THEN
    motorLatch := FALSE;
ELSIF Start THEN
    motorLatch := TRUE;
END_IF

Motor := motorLatch AND EStop;

END_PROGRAM

PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;     // Momentary start pushbutton
    Stop : BOOL;      // Momentary stop pushbutton
    EStop : BOOL;     // Emergency stop, normally-closed: TRUE = healthy, FALSE = activated
END_VAR_INPUT

VAR_OUTPUT
    Motor : BOOL;     // Motor contactor
END_VAR_OUTPUT

VAR
    MotorState : BOOL; // Internal state to track motor latching
END_VAR

IF NOT EStop THEN
    // Emergency stop is activated, immediately de-energize the motor
    MotorState := FALSE;
ELSIF Stop THEN
    // Stop button pressed, de-energize the motor
    MotorState := FALSE;
ELSIF Start THEN
    // Start button pressed, energize the motor
    MotorState := TRUE;
END_IF

// Output the motor state to the motor contactor
Motor := MotorState;

END_PROGRAM

