    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
ELSE
    (* Maintain current state of PumpIn *)
END_IF;

IF Level >= HighLimit THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

(* Safety check to ensure PumpIn is off when Level is at or above HighLimit *)
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

