PROGRAM tank_level
VAR_INPUT
    Level : INT; // Measured tank level in percent
END_VAR_INPUT

VAR_OUTPUT
    PumpIn : BOOL := FALSE; // Inlet pump
    ValveOut : BOOL := FALSE; // Outlet drain valve
END_VAR_OUTPUT

VAR
    low_limit : INT := 10; // Low limit for the hysteresis
    high_limit : INT := 90; // High limit for the hysteresis
    PumpInAllowed : BOOL := TRUE; // Internal flag to allow PumpIn operation
END_VAR

BEGIN
    // Safety condition: Ensure PumpIn is OFF when level is at or above the high limit
    IF Level >= high_limit THEN
        PumpInAllowed := FALSE;
        PumpIn := FALSE;
        ValveOut := TRUE; // Open valve to drain excess
    ELSE
        ValveOut := FALSE;
    END_IF;

    // Control logic to maintain tank level using hysteresis
    IF Level <= low_limit THEN
        PumpInAllowed := TRUE;
    END_IF;

    IF PumpInAllowed AND (Level < high_limit) THEN
        IF Level <= low_limit THEN
            PumpIn := TRUE;
        ELSIF Level >= high_limit THEN
            PumpIn := FALSE;
        END_IF;
    ELSE
        PumpIn := FALSE;
    END_IF;
END_PROGRAM

