PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR

VAR
    OpenA_Timer : TON;
    OpenB_Timer : TON;
END_VAR

(* Control logic for door operations *)
IF OpenA_Cmd AND NOT DoorB THEN
    (* Command to open Door A if Door B is not open *)
    OpenA_Timer(IN := TRUE, PT := T#1s);
    DoorA := OpenA_Timer.Q;
ELSE
    (* Reset the timer and keep Door A closed if command is not active or Door B is open *)
    OpenA_Timer(IN := FALSE, PT := T#1s);
    DoorA := FALSE;
END_IF

IF OpenB_Cmd AND NOT DoorA THEN
    (* Command to open Door B if Door A is not open *)
    OpenB_Timer(IN := TRUE, PT := T#1s);
    DoorB := OpenB_Timer.Q;
ELSE
    (* Reset the timer and keep Door B closed if command is not active or Door A is open *)
    OpenB_Timer(IN := FALSE, PT := T#1s);
    DoorB := FALSE;
END_IF
END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL; // Request to open door A
    OpenB_Cmd : BOOL; // Request to open door B
END_VAR_INPUT

VAR_OUTPUT
    DoorA : BOOL; // Door A open
    DoorB : BOOL; // Door B open
END_VAR_OUTPUT

VAR
    TimerA : TON; // Timer for door A opening logic
    TimerB : TON; // Timer for door B opening logic
END_VAR

BEGIN
    // Initialize outputs
    DoorA := FALSE;
    DoorB := FALSE;

    // Priority logic and mutual exclusion control
    IF OpenA_Cmd THEN
        // Door A is given priority over Door B
        TimerA(IN := TRUE, PT := T#0s);
        TimerB(IN := FALSE, PT := T#0s);

        IF TimerA.Q AND NOT DoorB THEN
            DoorA := TRUE;
        END_IF
    ELSIF OpenB_Cmd THEN
        // Open Door B only if Door A is not open
        TimerA(IN := FALSE, PT := T#0s);
        TimerB(IN := TRUE, PT := T#0s);

        IF TimerB.Q AND NOT DoorA THEN
            DoorB := TRUE;
        END_IF
    ELSE
        // No command, make sure both doors remain closed
        TimerA(IN := FALSE, PT := T#0s);
        TimerB(IN := FALSE, PT := T#0s);
    END_IF
END_PROGRAM

