    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR

VAR
    State : INT := 0;
    TimerGreen : TON;
    TimerYellow : TON;
    TimerAllRed : TON;
END_VAR

VAR CONSTANT
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

TimerGreen(IN := (State = 0) OR (State = 3), PT := PT_GREEN);
TimerYellow(IN := (State = 1) OR (State = 4), PT := PT_YELLOW);
TimerAllRed(IN := (State = 2) OR (State = 5), PT := PT_ALLRED);

CASE State OF
    0: // NS green, EW red
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TimerGreen.Q THEN
            State := 1;
        END_IF;

    1: // NS yellow, EW red
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TimerYellow.Q THEN
            State := 2;
        END_IF;

    2: // All-red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TimerAllRed.Q THEN
            State := 3;
        END_IF;

    3: // EW green, NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        IF TimerGreen.Q THEN
            State := 4;
        END_IF;

    4: // EW yellow, NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        IF TimerYellow.Q THEN
            State := 5;
        END_IF;

    5: // All-red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        IF TimerAllRed.Q THEN
            State := 0;
        END_IF;

ELSE
    State := 0; // Default to a safe state
END_CASE;
END_PROGRAM

