PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    StartMoving : BOOL := FALSE;
    UpTimer : TON;
    DownTimer : TON;
END_VAR

MotorUp := FALSE;
MotorDown := FALSE;

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed AND NOT AtTop THEN
            StartMoving := TRUE;
        END_IF;
        IF StartMoving THEN
            MotorUp := TRUE;
            IF DoorClosed THEN
                UpTimer(IN := TRUE, PT := T#3s);
                IF UpTimer.Q THEN
                    State := 1;
                    StartMoving := FALSE;
                    UpTimer(IN := FALSE);
                END_IF;
            ELSE
                MotorUp := FALSE;
            END_IF;
        END_IF;

    1: // Moving-up
        MotorUp := DoorClosed AND NOT AtTop;
        IF AtTop THEN
            State := 2;
        END_IF;

    2: // At-top
        IF CallDown AND DoorClosed AND NOT AtBottom THEN
            StartMoving := TRUE;
        END_IF;
        IF StartMoving THEN
            MotorDown := TRUE;
            IF DoorClosed THEN
                DownTimer(IN := TRUE, PT := T#3s);
                IF DownTimer.Q THEN
                    State := 3;
                    StartMoving := FALSE;
                    DownTimer(IN := FALSE);
                END_IF;
            ELSE
                MotorDown := FALSE;
            END_IF;
        END_IF;

    3: // Moving-down
        MotorDown := DoorClosed AND NOT AtBottom;
        IF AtBottom THEN
            State := 0;
        END_IF;

ELSE
    State := 0; // Default to At-bottom if in an unexpected state
END_CASE;

IF MotorUp AND MotorDown THEN
    MotorUp := FALSE;
    MotorDown := FALSE;
END_IF;

END_PROGRAM

