PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT; // range [0, 100]
    Temp : INT; // range [0, 200]
    EStop : BOOL; // TRUE = healthy, FALSE = activated
END_VAR_INPUT

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR_OUTPUT

VAR
    State : INT; // range [0, 4]
    ReactTimer : TON;
END_VAR

VAR CONSTANT
    LVL_HIGH : INT := 80;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
END_VAR CONSTANT

ReactTimer(IN := (State = 3), PT := PT_REACT);

IF NOT EStop THEN
    // Emergency stop activated
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF StartBatch THEN
                State := 1;
            END_IF;
        1: // Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State := 2;
            END_IF;
        2: // Heat
            FillValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;
        3: // React
            FillValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
            DrainValve := FALSE;
            IF ReactTimer.Q THEN
                State := 4;
            END_IF;
        4: // Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State := 0;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT; // 0..100
    Temp : INT; // 0..200
    EStop : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR_OUTPUT

VAR
    State : INT; // 0..4
    Timer : TON;
    TimerActive : BOOL;
END_VAR

VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    LIQ_MIN : INT := 10;
    PT_REACT : TIME := T#3s;
END_VAR CONSTANT

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            IF StartBatch THEN
                State := 1;
            END_IF;
        1: // Fill
            FillValve := Level < LVL_HIGH;
            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State := 2;
            END_IF;
        2: // Heat
            Heater := Level >= LIQ_MIN AND Temp < TEMP_SET;
            Agitator := Level >= LIQ_MIN;
            IF Temp >= TEMP_SET THEN
                State := 3;
                TimerActive := TRUE;
                Timer(IN := TRUE, PT := PT_REACT);
            END_IF;
        3: // React
            Heater := Level >= LIQ_MIN;
            Agitator := Level >= LIQ_MIN;
            Timer(IN := TimerActive, PT := PT_REACT);
            IF Timer.Q THEN
                State := 4;
                TimerActive := FALSE;
            END_IF;
        4: // Drain
            DrainValve := Level > LVL_LOW;
            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State := 0;
            END_IF;
    END_CASE;

    // Ensure valves are not open together
    IF FillValve THEN
        DrainValve := FALSE;
    END_IF;

    // Ensure heater and agitator are off if level is too low
    IF Level < LIQ_MIN THEN
        Heater := FALSE;
        Agitator := FALSE;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
