        Count := Count - 1;
    END_IF
END_IF

FullSign := (Count = 3);

IF EntryReq AND (Count < 3) THEN
    EntryBarrierOpen := TRUE;
ELSE
    EntryBarrierOpen := FALSE;
END_IF

PrevEntry := EntrySensor;
PrevExit := ExitSensor;
END_PROGRAM

