    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR

VAR
    State : INT := 0;
    StarTimer : TON;
END_VAR

StarTimer(IN := (State = 1), PT := T#3s);

CASE State OF
    0:  (* Off State *)
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:  (* Star State *)
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF StarTimer.Q THEN
            State := 2;
        END_IF;

    2:  (* Delta State *)
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        END_IF;

END_CASE;

END_PROGRAM

