    TimerIgnition : TON;
END_VAR

TimerPurge(IN := (State = 1), PT := T#3s);
TimerIgnition(IN := (State = 2), PT := T#2s);

CASE State OF
    0:  (* Off state *)
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:  (* Pre-purge state *)
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF TimerPurge.Q THEN
            State := 2;
        END_IF;

    2:  (* Ignition trial state *)
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF TimerIgnition.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3:  (* Run state *)
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR NOT EStop OR StopPB THEN
            State := 0;
        END_IF;
