    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    TimerPurge : TON;
    TimerIgnition : TON;
END_VAR

TimerPurge(IN := (State = 1), PT := T#3s);
TimerIgnition(IN := (State = 2), PT := T#2s);

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop AND NOT StopPB THEN
            State := 1; // Transition to Pre-purge
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT StartPB OR NOT EStop OR StopPB THEN
            State := 0; // Return to Off
        ELSIF TimerPurge.Q THEN
            State := 2; // Transition to Ignition trial
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE; // Fuel valve can only open with fan running
        Ignition := TRUE; // Igniter only on with fuel present
        IF NOT StartPB OR NOT EStop OR StopPB THEN
            State := 0; // Return to Off
        ELSIF TimerIgnition.Q THEN
            IF Flame THEN
                State := 3; // Transition to Run
            ELSE
                State := 0; // Failed ignition, return to Off
            END_IF;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR NOT StartPB OR NOT EStop OR StopPB THEN
            State := 0; // Return to Off if flame is lost or stopped
        END_IF;
END_CASE;
END_PROGRAM

