PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0; (* 0 = pump 1 leads, 1 = pump 2 leads *)
    PrevDemand : BOOL := FALSE;
END_VAR

BEGIN
    IF NOT EStop THEN
        Pump1 := FALSE;
        Pump2 := FALSE;
    ELSE
        IF Demand AND NOT PrevDemand THEN
            (* Rising edge of Demand - no action required here *)
        ELSIF NOT Demand AND PrevDemand THEN
            (* Falling edge of Demand - alternate the lead pump *)
            IF Lead = 0 THEN
                Lead := 1;
            ELSE
                Lead := 0;
            END_IF;
        END_IF;

        (* Control pumps based on lead and demand *)
        IF Demand THEN
            CASE Lead OF
                0:
                    Pump1 := TRUE;
                    Pump2 := FALSE;
                1:
                    Pump1 := FALSE;
                    Pump2 := TRUE;
            ELSE
                (* Fail-safe: both pumps off *)
                Pump1 := FALSE;
                Pump2 := FALSE;
            END_CASE;
        ELSE
            Pump1 := FALSE;
            Pump2 := FALSE;
        END_IF;
    END_IF;

    (* Update PrevDemand for edge detection *)
    PrevDemand := Demand;
END_PROGRAM

