    PrevTrigger : BOOL := FALSE;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF NOT PrevTrigger AND Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;

    IF Count = 3 THEN
        Done := TRUE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    Done : BOOL;
END_VAR_OUTPUT

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSE
    IF Trigger AND NOT PrevTrigger THEN
        IF Count < 3 THEN
            Count := Count + 1;
        END_IF;
    END_IF;

    IF Count >= 3 THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM

